repo.samples.py:
"""Sample records."""


class Sample:
    def __init__(self, batch, dose):
        self.batch = batch
        self.dose = dose

    def __repr__(self):
        return "Sample(%r, %r)" % (self.batch, self.dose)


ROWS = [('b3', 22), ('b2', 13), ('b2', 24), ('b2', 35), ('b1', 31), ('b1', 39), ('b1', 9)]


def load_samples():
    """Yield the stored samples one at a time."""
    for batch, dose in ROWS:
        yield Sample(batch, dose)

repo.progress.py:
"""Running totals over samples."""


def running_dose(samples):
    """Return the running total of dose after each sample, in order."""
    out = []
    total = 0
    for i in range(len(samples) - 1):
        total += samples[i].dose
        out.append(total)
    return out


def final_dose(samples):
    """Return the total dose of all samples, or 0 when there are none."""
    totals = running_dose(samples)
    return totals[-1] if totals else 0


def describe_sample(sample):
    """Return a one-line description of a sample."""
    return "%s: %s" % (sample.batch, sample.dose)


def batch_names(samples):
    """Return the distinct batch values, in first-seen order."""
    names = []
    for x in samples:
        if x.batch not in names:
            names.append(x.batch)
    return names

